package de.jannika.planttracker.scheduler;

import java.time.LocalDate;

import org.springframework.boot.context.event.ApplicationReadyEvent;
import org.springframework.context.event.EventListener;
import org.springframework.stereotype.Component;

import de.jannika.planttracker.service.WeatherService;

/**
 * Component for triggering automated weather data synchronization tasks.
 * 
 * @note This class was initially generated by an LLM in summer (June/July) 2026. 
 *       It has been reviewed, troubleshooted, and verified to ensure 
 *       reliable background execution without requiring major modifications.
 */

@Component
public class WeatherScheduler {

    private final WeatherService weatherService;

    public WeatherScheduler(WeatherService weatherService) {
        this.weatherService = weatherService;
    }

    @EventListener(ApplicationReadyEvent.class)
    public void triggerStartupWeatherSync() {
        // Run the sync process inside a separate thread so it doesn't block the main startup sequence
        new Thread(() -> {
            try {
                Thread.sleep(2000);
                
                LocalDate today = LocalDate.now();
                System.out.println("Starting automated background weather check for the past 7 days...");

                for (int i = 1; i <= 7; i++) {
                    LocalDate targetDate = today.minusDays(i);

                    if (!weatherService.hasWeatherDataForDate(targetDate)) {
                        System.out.println("Missing data detected for " + targetDate + ". Requesting remote update API...");
                        weatherService.syncHistoricalWeather(targetDate);
                    } else {
                        System.out.println("Weather data already exists for " + targetDate + ". Skipping.");
                    }
                }
                System.out.println("Startup weather synchronization completed successfully.");
            } catch (Exception e) {
                System.err.println("Weather background worker encountered an interruption: " + e.getMessage());
            }
        }).start();
    }
    
}
